{
  "tests": [
    {
      "id": "ca-et-factures-tableau-de-bord-liste",
      "titre": "Tableau de bord : CA du mois et factures du mois",
      "setup": "Connecté avec le compte de démo, sur le tableau de bord, sans filtre.",
      "etapes": [
        "Ouvrir le menu « Factures ».",
        "Sélectionner l'option « Liste des factures »."
      ],
      "resultat_attendu": "Le CA du mois et le nombre de factures du mois correspondent aux totaux de la liste des factures.",
      "verifications": [
        "FAIL if le CA du mois affiché n’est pas égal au total affiché dans la liste des factures.",
        "FAIL if le nombre de factures du mois affiché n’est pas égal au nombre de factures indiqué dans la liste."
      ],
      "releves": [
        { "ecran": "tableau-de-bord", "vue": "defaut" },
        { "ecran": "liste-des-factures", "vue": "defaut" }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": { "ecran": "tableau-de-bord", "champ": "CA du mois" },
          "b": { "ecran": "liste-des-factures", "champ": "Total" }
        },
        {
          "type": "egalite",
          "a": { "ecran": "tableau-de-bord", "champ": "Factures du mois" },
          "b": { "ecran": "liste-des-factures", "champ": "Nombre de factures" }
        }
      ],
      "passages_de_la_source": [
        "Le « CA du mois » du [[tableau-de-bord]] est égal au total de la [[liste-des-factures]].",
        "Le nombre de « Factures du mois » du [[tableau-de-bord]] est égal au nombre de factures de la [[liste-des-factures]]."
      ],
      "questions": []
    },
    {
      "id": "total-ttc-detail-facture-liste",
      "titre": "Détail de facture : Total TTC",
      "setup": "Connecté avec le compte de démo, sur la liste des factures, sans filtre.",
      "etapes": [
        "Cliquer sur le numéro de facture « F-119 »."
      ],
      "resultat_attendu": "Le Total TTC du détail de la facture correspond au montant TTC indiqué dans la liste des factures.",
      "verifications": [
        "FAIL if le Total TTC affiché n’est pas égal au montant TTC de la facture F-119 dans la liste des factures."
      ],
      "releves": [
        { "ecran": "liste-des-factures", "vue": "defaut" },
        { "ecran": "detail-facture", "vue": "defaut" }
      ],
      "regles_calculables": [
        {
          "type": "egalite",
          "a": { "ecran": "detail-facture", "champ": "Total TTC" },
          "b": { "ecran": "liste-des-factures", "champ": "Montant TTC de F-119" }
        }
      ],
      "passages_de_la_source": [
        "Le « Total TTC » du [[detail-facture]] est égal au montant de la même facture dans la [[liste-des-factures]]. Facture témoin : F-119."
      ],
      "questions": []
    }
  ]
}

